//! Metadata validation middleware.

use crate::metadata::{KeyAndValueRef, MetadataMap};
use crate::Status;
use pin_project::pin_project;
use std::future::Future;
use std::pin::Pin;
use std::sync::Arc;
use std::task::{Context, Poll};
use tower_layer::Layer;
use tower_service::Service;

/// Validates incoming request metadata.
pub trait MetadataValidator {
    /// Validate `metadata`.
    fn validate(&self, metadata: &MetadataMap) -> Result<(), Status>;
}

#[derive(Debug)]
enum Rule {
    RequireHeader(&'static str),
    MaxHeaderSize(usize),
    HeaderPrefix {
        name: &'static str,
        prefix: &'static str,
    },
    MaxTotalHeaders(usize),
}

/// Fluent builder for composing metadata validation rules.
#[derive(Debug, Default)]
pub struct ValidatorBuilder {
    rules: Vec<Rule>,
}

impl ValidatorBuilder {
    /// Create an empty validator.
    pub fn new() -> Self {
        Self { rules: Vec::new() }
    }

    /// Require the header `name` to be present.
    ///
    /// Missing headers return a `failed_precondition` status.
    pub fn require_header(mut self, name: &'static str) -> Self {
        self.rules.push(Rule::RequireHeader(name));
        self
    }

    /// Set a max size, in bytes, for any single header value.
    ///
    /// Violations return an `invalid_argument` status.
    pub fn max_header_size(mut self, limit: usize) -> Self {
        self.rules.push(Rule::MaxHeaderSize(limit));
        self
    }

    /// Require header `name` to have a value starting with `prefix`.
    ///
    /// Violations return an `invalid_argument` status.
    pub fn header_prefix(mut self, name: &'static str, prefix: &'static str) -> Self {
        self.rules.push(Rule::HeaderPrefix { name, prefix });
        self
    }

    /// Limit the total number of header values.
    ///
    /// Violations return a `resource_exhausted` status.
    pub fn max_total_headers(mut self, limit: usize) -> Self {
        self.rules.push(Rule::MaxTotalHeaders(limit));
        self
    }
}

impl MetadataValidator for ValidatorBuilder {
    fn validate(&self, metadata: &MetadataMap) -> Result<(), Status> {
        let mut i = 0usize;

        while i < self.rules.len() {
            match &self.rules[i] {
                Rule::RequireHeader(name) => {
                    if !header_present(metadata, name) {
                        return Err(Status::failed_precondition(
                            "missing required metadata header",
                        ));
                    }
                }
                Rule::MaxHeaderSize(limit) => {
                    let mut iter = metadata.iter();

                    loop {
                        match iter.next() {
                            Some(KeyAndValueRef::Ascii(_, value)) => {
                                if value.as_bytes().len() > *limit {
                                    return Err(Status::invalid_argument(
                                        "metadata header value too large",
                                    ));
                                }
                            }
                            Some(KeyAndValueRef::Binary(_, value)) => {
                                if value.as_bytes().len() > *limit {
                                    return Err(Status::invalid_argument(
                                        "metadata header value too large",
                                    ));
                                }
                            }
                            None => {
                                break;
                            }
                        }
                    }
                }
                Rule::HeaderPrefix { name, prefix } => {
                    match metadata.get(*name) {
                        Some(value) => match value.to_str() {
                            Ok(text) => {
                                if !text.starts_with(prefix) {
                                    return Err(Status::invalid_argument(
                                        "metadata header has invalid prefix",
                                    ));
                                }
                            }
                            Err(_) => {
                                return Err(Status::invalid_argument(
                                    "metadata header value is not valid UTF-8",
                                ));
                            }
                        },
                        None => {
                            return Err(Status::invalid_argument(
                                "missing metadata header for prefix check",
                            ));
                        }
                    }
                }
                Rule::MaxTotalHeaders(limit) => {
                    if metadata.len() > *limit {
                        return Err(Status::resource_exhausted(
                            "too many metadata headers",
                        ));
                    }
                }
            }

            i += 1;
        }

        Ok(())
    }
}

fn header_present(metadata: &MetadataMap, name: &str) -> bool {
    if name.ends_with("-bin") {
        match metadata.get_bin(name) {
            Some(_) => true,
            None => false,
        }
    } else {
        metadata.contains_key(name)
    }
}

/// A Tower layer that validates request metadata.
#[derive(Debug)]
pub struct MetadataValidatorLayer<V> {
    validator: Arc<V>,
}

impl<V> MetadataValidatorLayer<V> {
    /// Create a new layer.
    pub fn new(validator: V) -> Self {
        Self {
            validator: Arc::new(validator),
        }
    }
}

impl<V> Clone for MetadataValidatorLayer<V> {
    fn clone(&self) -> Self {
        Self {
            validator: Arc::clone(&self.validator),
        }
    }
}

impl<S, V> Layer<S> for MetadataValidatorLayer<V>
where
    V: MetadataValidator,
{
    type Service = MetadataValidatedService<S, V>;

    fn layer(&self, inner: S) -> Self::Service {
        MetadataValidatedService {
            inner,
            validator: Arc::clone(&self.validator),
        }
    }
}

/// Service produced by [`MetadataValidatorLayer`].
#[derive(Debug)]
pub struct MetadataValidatedService<S, V> {
    inner: S,
    validator: Arc<V>,
}

impl<S, V> Clone for MetadataValidatedService<S, V>
where
    S: Clone,
{
    fn clone(&self) -> Self {
        Self {
            inner: self.inner.clone(),
            validator: Arc::clone(&self.validator),
        }
    }
}

impl<S, V, ReqBody, ResBody> Service<http::Request<ReqBody>>
    for MetadataValidatedService<S, V>
where
    S: Service<http::Request<ReqBody>, Response = http::Response<ResBody>>,
    V: MetadataValidator,
    ResBody: http_body::Body,
{
    type Response = http::Response<ResponseBody<ResBody>>;
    type Error = S::Error;
    type Future = MetadataValidatedFuture<S::Future, ResBody>;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)
    }

    fn call(&mut self, req: http::Request<ReqBody>) -> Self::Future {
        let req = crate::Request::from_http(req);

        match self.validator.validate(req.metadata()) {
            Ok(()) => {
                let http_req = req.into_http();
                MetadataValidatedFuture::new(Kind::Future {
                    future: self.inner.call(http_req),
                })
            }
            Err(status) => MetadataValidatedFuture::new(Kind::Status {
                status: Some(status),
            }),
        }
    }
}

#[pin_project]
#[derive(Debug)]
pub struct MetadataValidatedFuture<F, B> {
    #[pin]
    kind: Kind<F>,
    _body: std::marker::PhantomData<B>,
}

#[pin_project(project = KindProj)]
#[derive(Debug)]
enum Kind<F> {
    Future {
        #[pin]
        future: F,
    },
    Status {
        status: Option<Status>,
    },
}

impl<F, B> MetadataValidatedFuture<F, B> {
    fn new(kind: Kind<F>) -> Self {
        Self {
            kind,
            _body: std::marker::PhantomData,
        }
    }
}

impl<F, E, B> Future for MetadataValidatedFuture<F, B>
where
    F: Future<Output = Result<http::Response<B>, E>>,
    B: http_body::Body,
{
    type Output = Result<http::Response<ResponseBody<B>>, E>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        match self.project().kind.project() {
            KindProj::Future { future } => match future.poll(cx) {
                Poll::Ready(Ok(res)) => Poll::Ready(Ok(res.map(ResponseBody::wrap))),
                Poll::Ready(Err(err)) => Poll::Ready(Err(err)),
                Poll::Pending => Poll::Pending,
            },
            KindProj::Status { status } => {
                let status = match status.take() {
                    Some(status) => status,
                    None => Status::internal(
                        "metadata validator future polled after completion",
                    ),
                };

                let (parts, ()) = status.into_http::<()>().into_parts();
                let response = http::Response::from_parts(parts, ResponseBody::<B>::empty());
                Poll::Ready(Ok(response))
            }
        }
    }
}

/// Response body for [`MetadataValidatedService`].
#[pin_project]
#[derive(Debug)]
pub struct ResponseBody<B> {
    #[pin]
    kind: ResponseBodyKind<B>,
}

#[pin_project(project = ResponseBodyKindProj)]
#[derive(Debug)]
enum ResponseBodyKind<B> {
    Empty,
    Wrap(#[pin] B),
}

impl<B> ResponseBody<B> {
    fn new(kind: ResponseBodyKind<B>) -> Self {
        Self { kind }
    }

    fn empty() -> Self {
        Self::new(ResponseBodyKind::Empty)
    }

    fn wrap(body: B) -> Self {
        Self::new(ResponseBodyKind::Wrap(body))
    }
}

impl<B: http_body::Body> http_body::Body for ResponseBody<B> {
    type Data = B::Data;
    type Error = B::Error;

    fn poll_frame(
        self: Pin<&mut Self>,
        cx: &mut Context<'_>,
    ) -> Poll<Option<Result<http_body::Frame<Self::Data>, Self::Error>>> {
        match self.project().kind.project() {
            ResponseBodyKindProj::Empty => Poll::Ready(None),
            ResponseBodyKindProj::Wrap(body) => body.poll_frame(cx),
        }
    }

    fn size_hint(&self) -> http_body::SizeHint {
        match &self.kind {
            ResponseBodyKind::Empty => http_body::SizeHint::with_exact(0),
            ResponseBodyKind::Wrap(body) => body.size_hint(),
        }
    }

    fn is_end_stream(&self) -> bool {
        match &self.kind {
            ResponseBodyKind::Empty => true,
            ResponseBodyKind::Wrap(body) => body.is_end_stream(),
        }
    }
}
